/**
 * Verify that the epicshop package is available on npm registry
 * This helps avoid 404 errors in workshop CI when npm registry replication is delayed
 */
async function verifyPackageAvailability(
	packageName,
	version,
	maxRetries = 20,
) {
	// For scoped packages like @epic-web/workshop-app, extract just the package name part
	const tarballName = packageName.includes('/')
		? packageName.split('/')[1]
		: packageName

	for (let attempt = 1; attempt <= maxRetries; attempt++) {
		try {
			// Use AbortController for proper timeout handling
			const controller = new AbortController()
			const timeoutId = setTimeout(() => controller.abort(), 5000)

			// Use GET instead of HEAD to match what workshop CI does during install
			// npm registry has had inconsistent HEAD responses for scoped packages
			const response = await fetch(
				`https://registry.npmjs.org/${packageName}/-/${tarballName}-${version}.tgz`,
				{
					method: 'GET',
					signal: controller.signal,
				},
			)
			clearTimeout(timeoutId)

			if (response.ok) {
				console.log(`✅ ${packageName}@${version} is available on npm registry`)
				return true
			}
			if (response.status !== 404) {
				console.log(
					`⚠️  Unexpected status ${response.status} when checking ${packageName}@${version}, retrying...`,
				)
			}
		} catch (error) {
			console.log(
				`⚠️  Network error checking ${packageName}@${version}: ${error.message}`,
			)
		}

		if (attempt < maxRetries) {
			const waitSeconds = Math.min(2 ** (attempt - 1), 30)
			console.log(
				`⏳ Package not available yet (attempt ${attempt}/${maxRetries}). Waiting ${waitSeconds}s before retry...`,
			)
			await delay(waitSeconds * 1000)
		}
	}

	// Calculate approximate wait time: sum of exponential backoff + fetch timeouts
	const backoffSum = Array.from({ length: maxRetries - 1 }, (_, i) =>
		Math.min(2 ** i, 30),
	).reduce((a, b) => a + b, 0)
	const totalSeconds = backoffSum + maxRetries * 5
	const totalMinutes = Math.round(totalSeconds / 60)

	console.warn(
		`⚠️  ${packageName}@${version} was not available on npm after ${maxRetries} retries (~${totalMinutes} minute${totalMinutes !== 1 ? 's' : ''}).`,
	)
	console.warn(
		'This may cause workshop CI failures. Consider running the update again later.',
	)
	return false
}

async function pullRebaseWithFallback(cwd) {
	try {
		await execa('git', ['pull', '--rebase'], { cwd, env: getGitEnv() })
	} catch {
		// Shallow clones sometimes can't rebase/pull without more history.
		try {
			await execa('git', ['fetch', '--unshallow'], { cwd, env: getGitEnv() })
		} catch {
			await execa('git', ['fetch', '--depth=50'], { cwd, env: getGitEnv() })
		}
		await execa('git', ['pull', '--rebase'], { cwd, env: getGitEnv() })
	}
}

/**
 * Keep workshop deploy workflows aligned with the retrying canonical template.
 */
async function syncDeployWorkflow(workshopDir) {
	const targetPath = path.join(workshopDir, DEPLOY_WORKFLOW_PATH)
	const canonical = await fs.readFile(CANONICAL_DEPLOY_WORKFLOW, 'utf8')
	let current = null
	try {
		current = await fs.readFile(targetPath, 'utf8')
	} catch (error) {
		if (error?.code !== 'ENOENT') throw error
	}

	if (current === canonical) {
		return { changed: false, path: DEPLOY_WORKFLOW_PATH }
	}

	await fs.mkdir(path.dirname(targetPath), { recursive: true })
	await fs.writeFile(targetPath, canonical, 'utf8')
	return { changed: true, path: DEPLOY_WORKFLOW_PATH }
}

/**
 * Lengthen Fly health-check grace periods so cold boots are not raced.
 * App names differ per workshop, so patch in place instead of overwriting.
 */
async function patchFlyHealthGracePeriods(workshopDir) {
	const flyPath = path.join(workshopDir, FLY_CONFIG_PATH)
	let contents
	try {
		contents = await fs.readFile(flyPath, 'utf8')
	} catch (error) {
		if (error?.code === 'ENOENT') {
			return { changed: false, path: FLY_CONFIG_PATH, missing: true }
		}
		throw error
	}

	let section = null
	let httpChecks = 0
	let tcpChecks = 0
	const next = contents
		.split('\n')
		.map((line) => {
			const trimmed = line.trim()
			if (trimmed === 'http_checks:') {
				section = 'http'
				return line
			}
			if (trimmed === 'tcp_checks:') {
				section = 'tcp'
				return line
			}
			// Leave the current checks block when indentation returns to the
			// services list / top-level keys.
			if (
				section &&
				trimmed &&
				!line.startsWith(' ') &&
				!line.startsWith('\t')
			) {
				section = null
			} else if (
				section &&
				/^[A-Za-z_][\w-]*:\s*$/.test(trimmed) &&
				!trimmed.endsWith('checks:')
			) {
				const indent = line.match(/^\s*/)?.[0].length ?? 0
				if (indent <= 4) section = null
			}

			if (section && /^\s*grace_period:\s*\S+\s*$/.test(line)) {
				if (section === 'http') {
					httpChecks += 1
					return line.replace(/grace_period:\s*\S+/, 'grace_period: 60s')
				}
				tcpChecks += 1
				return line.replace(/grace_period:\s*\S+/, 'grace_period: 30s')
			}
			return line
		})
		.join('\n')

	if (next === contents) {
		return { changed: false, path: FLY_CONFIG_PATH, httpChecks, tcpChecks }
	}

	await fs.writeFile(flyPath, next, 'utf8')
	return { changed: true, path: FLY_CONFIG_PATH, httpChecks, tcpChecks }
}

/**
 * Update package.json files - only root and epicshop/package.json
 */
async function updatePackageJsonFiles(workshopDir, version) {
	const pkgs = ['package.json', 'epicshop/package.json']
	const changedPkgs = []
	const existingPkgs = []
	let changed = false

	for (const pkg of pkgs) {
		const pkgPath = path.join(workshopDir, pkg)
		try {
			const contents = await fs.readFile(pkgPath, 'utf8')
			existingPkgs.push(pkg)
			const newContents = contents
				.replace(
					/(@epic-web\/workshop-[^":]+":\s*")([^"]+)"/g,
					`$1^${version}"`,
				)
				.replace(/(epicshop":\s*")([^"]+)"/g, `$1^${version}"`)

			if (contents !== newContents) {
				await fs.writeFile(pkgPath, newContents, 'utf8')
				changed = true
				changedPkgs.push(pkg)
			}
		} catch (error) {
			// File doesn't exist, skip it
			if (error?.code !== 'ENOENT') throw error
		}
	}

	return { changed, pkgs: existingPkgs, changedPkgs }
}

/**
 * Update a single workshop repository
 */
async function updateWorkshopRepo(repo, version) {
	const repoName = repo.name
	const repoUrl = getAuthenticatedRepoUrl(repoName)
	const tempDir = path.join(__dirname, 'temp-workshops', repoName)

	try {
		// Clean up temp directory if it exists
		await fs.rm(tempDir, { recursive: true, force: true }).catch(() => {})

		// Create temp directory
		await fs.mkdir(path.dirname(tempDir), { recursive: true })

		console.log(`🔍 ${repoName} - cloning repository with sparse checkout`)

		// Clone with sparse checkout - only get the 4 files we need
		await execa(
			'git',
			[
				'clone',
				'--depth=1',
				'--filter=blob:none',
				'--sparse',
				repoUrl,
				tempDir,
			],
			{
				env: getGitEnv(),
			},
		)

		// Configure sparse checkout in non-cone mode to allow file-level patterns
		// This lets us checkout only specific files (like package.json) from workspace dirs.
		// Include deploy workflow + fly config so mass updates can harden them too.
		await execa(
			'git',
			[
				'sparse-checkout',
				'set',
				'--no-cone',
				'/*',
				'epicshop/',
				'.github/workflows/',
			],
			{ cwd: tempDir, env: getGitEnv() },
		)

		// Ensure future push operations use an authenticated remote URL.
		// (Some git versions can normalize remotes in ways that drop credentials.)
		await execa('git', ['remote', 'set-url', 'origin', repoUrl], {
			cwd: tempDir,
			env: getGitEnv(),
		})

		// Update package.json files
		console.log(`📝 ${repoName} - updating package.json files`)
		const { changed, pkgs, changedPkgs } = await updatePackageJsonFiles(
			tempDir,
			version,
		)

		console.log(
			`🛠️  ${repoName} - syncing deploy workflow and Fly health grace`,
		)
		const workflowSync = await syncDeployWorkflow(tempDir)
		const flyPatch = await patchFlyHealthGracePeriods(tempDir)
		if (workflowSync.changed) {
			console.log(`🛠️  ${repoName} - updated ${workflowSync.path}`)
		}
		if (flyPatch.changed) {
			console.log(
				`🛠️  ${repoName} - updated ${flyPatch.path} health grace periods`,
			)
		}

		if (!changed && !workflowSync.changed && !flyPatch.changed) {
			console.log(`🟢 ${repoName} - already up to date`)
			return { repo: repoName, status: 'up-to-date' }
		}

		// Run npm install only in directories where package.json changed
		// We only handle root and epicshop directories
		const installDirs = []
		for (const pkg of changedPkgs) {
			const installDir =
				pkg === 'package.json' ? tempDir : path.join(tempDir, path.dirname(pkg))
			if (!installDirs.includes(installDir)) {
				installDirs.push(installDir)
			}
		}

		// Check if any install directory has workspaces - if so, we need to add
		// workspace package.json files to sparse checkout so npm can resolve them
		for (const installDir of installDirs) {
			const pkgJsonPath = path.join(installDir, 'package.json')
			try {
				const pkgJson = JSON.parse(await fs.readFile(pkgJsonPath, 'utf8'))
				if (pkgJson.workspaces) {
					const workspacePatterns = Array.isArray(pkgJson.workspaces)
						? pkgJson.workspaces
						: pkgJson.workspaces.packages || []
					console.log(
						`📦 ${repoName} - workspaces detected: ${JSON.stringify(workspacePatterns)}`,
					)

					// In non-cone mode, sparse-checkout uses gitignore-style patterns.
					// We add patterns for package.json files in each workspace directory.
					const sparsePatterns = workspacePatterns.map(
						(pattern) => `${pattern}/package.json`,
					)
					console.log(
						`📦 ${repoName} - adding sparse patterns: ${JSON.stringify(sparsePatterns)}`,
					)

					// Read current sparse-checkout patterns and append new ones
					const sparseCheckoutFile = path.join(
						tempDir,
						'.git',
						'info',
						'sparse-checkout',
					)
					const currentPatterns = await fs.readFile(sparseCheckoutFile, 'utf8')
					const newPatterns =
						currentPatterns.trim() + '\n' + sparsePatterns.join('\n') + '\n'
					await fs.writeFile(sparseCheckoutFile, newPatterns, 'utf8')

					// Re-apply sparse checkout to fetch the new files
					await execa('git', ['read-tree', '-mu', 'HEAD'], {
						cwd: tempDir,
						env: getGitEnv(),
					})

					// Verify checkout - count how many workspace package.json files exist
					const { stdout: checkedOutFiles } = await execa(
						'git',
						['ls-files', '--', ...sparsePatterns],
						{ cwd: tempDir, env: getGitEnv() },
					)
					const fileCount = checkedOutFiles
						? checkedOutFiles.split('\n').filter(Boolean).length
						: 0
					console.log(
						`📦 ${repoName} - checked out ${fileCount} workspace package.json files`,
					)
					if (fileCount > 0 && fileCount <= 20) {
						console.log(
							`      Files: ${checkedOutFiles.split('\n').filter(Boolean).join(', ')}`,
						)
					}
					break
				}
			} catch (error) {
				console.log(
					`⚠️  ${repoName} - error checking workspaces: ${error.message}`,
				)
			}
		}

		for (const installDir of installDirs) {
			const rel = path.relative(tempDir, installDir).replace(/\\/g, '/')
			console.log(`📦 ${repoName} - running npm install in ${rel || 'root'}`)
			try {
				const { stderr } = await execa('npm', ['install', '--ignore-scripts'], {
					cwd: installDir,
					env: getGitEnv(),
				})
				if (stderr) {
					console.log(`📦 ${repoName} - npm install stderr:\n${stderr}`)
				}
			} catch (error) {
				// If npm install fails, log the error details
				console.log(
					`⚠️  ${repoName} - npm install failed in ${rel || 'root'}: ${error.message}`,
				)
				if (error.stderr) {
					console.log(`      stderr: ${error.stderr}`)
				}
			}
		}

		// Stage package files, deploy workflow, and fly config when present.
		const filesToStage = []
		for (const pkg of pkgs) {
			const pkgPath = path.join(tempDir, pkg)
			try {
				await fs.access(pkgPath)
				filesToStage.push(pkg)
			} catch {
				// File doesn't exist, skip
			}
		}
		for (const pkg of pkgs) {
			const lockPath = pkg.replace('package.json', 'package-lock.json')
			const lockPathFull = path.join(tempDir, lockPath)
			try {
				await fs.access(lockPathFull)
				filesToStage.push(lockPath)

				// Log workspace packages in the lock file
				try {
					const lockContents = await fs.readFile(lockPathFull, 'utf8')
					const lockJson = JSON.parse(lockContents)
					const workspacePackages = Object.keys(lockJson.packages || {}).filter(
						(key) =>
							key.startsWith('exercises/') ||
							key.startsWith('extra/') ||
							key.startsWith('example/') ||
							key.startsWith('examples/'),
					)
					console.log(
						`📦 ${repoName} - package-lock.json contains ${workspacePackages.length} workspace package entries`,
					)
					if (workspacePackages.length > 0 && workspacePackages.length <= 10) {
						console.log(`      Entries: ${workspacePackages.join(', ')}`)
					} else if (workspacePackages.length > 10) {
						console.log(
							`      First 10: ${workspacePackages.slice(0, 10).join(', ')}...`,
						)
					}
				} catch (lockError) {
					console.log(
						`⚠️  ${repoName} - could not parse lock file: ${lockError.message}`,
					)
				}
			} catch {
				// File doesn't exist, skip
			}
		}
		if (workflowSync.changed) filesToStage.push(DEPLOY_WORKFLOW_PATH)
		if (flyPatch.changed) filesToStage.push(FLY_CONFIG_PATH)

		// Some workshop repos gitignore files we'd otherwise stage (e.g.
		// epicshop/package-lock.json) and `git add` fails on ignored files.
		const stageableFiles = []
		for (const file of filesToStage) {
			// check-ignore exits 0 when the file is ignored and 1 when it's not
			const { exitCode } = await execa('git', ['check-ignore', '-q', file], {
				cwd: tempDir,
				env: getGitEnv(),
				reject: false,
			})
			if (exitCode === 0) {
				console.log(`🙈 ${repoName} - skipping gitignored file: ${file}`)
			} else {
				stageableFiles.push(file)
			}
		}

		// Stage changes
		console.log(
			`📝 ${repoName} - staging changes: ${stageableFiles.join(', ')}`,
		)
		if (stageableFiles.length > 0) {
			await execa('git', ['add', ...stageableFiles], {
				cwd: tempDir,
				env: getGitEnv(),
			})
		}

		// Check if there are actually staged changes
		const { stdout: diffOutput } = await execa(
			'git',
			['diff', '--cached', '--name-only'],
			{ cwd: tempDir },
		)
		if (!diffOutput.trim()) {
			console.log(`🟢 ${repoName} - no changes to commit`)
			return { repo: repoName, status: 'no-changes' }
		}

		const commitMessage = changed
			? 'chore: update epicshop'
			: 'chore: harden fly deploy workflow'

		// Commit changes
		console.log(`💾 ${repoName} - committing changes`)
		await execa('git', ['commit', '-m', commitMessage], {
			cwd: tempDir,
			env: getGitEnv(),
		})

		// Push changes (retry once with a pull/rebase if needed), staggered so
		// the resulting deploy workflows do not all hit Fly at once.
		await withPushStagger(async () => {
			console.log(`⬆️  ${repoName} - pushing changes`)
			try {
				await execa('git', ['push'], {
					cwd: tempDir,
					env: getGitEnv(),
				})
			} catch {
				await pullRebaseWithFallback(tempDir)
				await execa('git', ['push'], {
					cwd: tempDir,
					env: getGitEnv(),
				})
			}
		})

		console.log(`✅ ${repoName} - updated successfully`)
		return { repo: repoName, status: 'updated' }
	} catch (error) {
		console.error(`❌ ${repoName} - failed:`, error.message)
		if (error.all) {
			console.error(error.all)
		}
		const message = String(error?.message ?? error)
		const authHint =
			message.includes('Authentication failed') ||
			message.includes('could not read Password') ||
			message.includes('terminal prompts disabled') ||
			message.includes('403')
				? ' (auth issue: ensure WORKSHOP_UPDATE_TOKEN is a PAT with write access to these repos)'
				: ''
		return {
			repo: repoName,
			status: 'failed',
			error: `${message}${authHint}`,
		}
	} finally {
		// Clean up temp directory
		await fs.rm(tempDir, { recursive: true, force: true }).catch(() => {})
	}
}

/**
 * Main function
 */
async function main() {
	try {
		console.log(
			`🔐 Auth: using ${USING_WORKSHOP_UPDATE_TOKEN ? 'WORKSHOP_UPDATE_TOKEN' : 'GITHUB_TOKEN'}`,
		)
		console.log('🔍 Fetching workshop repositories from GitHub...')
		const workshops = await fetchAvailableWorkshops()
		workshops.push(...(await fetchAdditionalWorkshops(workshops)))

		if (workshops.length === 0) {
			console.log('⚠️  No workshops found')
			return
		}

		console.log(`📚 Found ${workshops.length} workshop repositories:`)
		workshops.forEach((w) => {
			console.log(`  - ${w.name}`)
		})
		console.log()

		console.log('📦 Getting latest version from npm...')
		const version = await getLatestVersion()
		console.log(`🔍 Updating to version ${version}`)
		await verifyWorkshopAppSupportsTargetNode(version)

		// Verify that both epicshop and workshop-app are available on npm
		// before pushing updates to workshops to avoid 404 errors in workshop CI
		console.log('\n🔐 Verifying package availability on npm registry...')
		const epicshopAvailable = await verifyPackageAvailability(
			'epicshop',
			version,
		)

		// If epicshop is not available, skip workshop-app check to avoid wasting time
		let workshopAppAvailable = false
		if (epicshopAvailable) {
			workshopAppAvailable = await verifyPackageAvailability(
				'@epic-web/workshop-app',
				version,
			)
		} else {
			console.log(
				'⏭️  Skipping @epic-web/workshop-app verification since epicshop is unavailable',
			)
		}

		if (!epicshopAvailable || !workshopAppAvailable) {
			console.error(
				'\n❌ Required packages not available on npm. Aborting to prevent workshop CI failures.',
			)
			console.error('   Please try running this script again in a few minutes.')
			process.exit(1)
		}

		console.log(
			`\n🚀 Processing ${workshops.length} repos with concurrency ${CONCURRENCY} (push stagger ${Math.round(PUSH_STAGGER_MS / 1000)}s)\n`,
		)

		// Process repos in parallel with a simple concurrency pool (no extra deps)
		const results = []
		const queue = [...workshops]
		const workers = Array.from({ length: CONCURRENCY }, async () => {
			while (queue.length) {
				const repo = queue.shift()
				if (!repo) break
				results.push(await updateWorkshopRepo(repo, version))
			}
		})
		await Promise.all(workers)

		// Summary
		const updated = results.filter((r) => r.status === 'updated')
		const skipped = results.filter(
			(r) =>
				r.status === 'skipped' ||
				r.status === 'up-to-date' ||
				r.status === 'no-changes',
		)
		const failed = results.filter((r) => r.status === 'failed')

		console.log('\n' + '='.repeat(50))
		console.log('📊 Summary:')
		console.log(`  ✅ Updated: ${updated.length}`)
		console.log(`  🟢 Skipped (up to date): ${skipped.length}`)
		console.log(`  ❌ Failed: ${failed.length}`)

		if (failed.length > 0) {
			console.log('\nFailed repositories:')
			failed.forEach((r) => {
				console.log(`  - ${r.repo}: ${r.error}`)
			})
		}

		console.log('\n✅ All workshops processed')

		// Exit with error if any failed
		if (failed.length > 0) {
			process.exit(1)
		}
	} catch (error) {
		console.error('❌ Fatal error:', error.message)
		process.exit(1)
	}
}

await main()

import path from "path";
import { execa } from "execa";
import getRegistry from "./get-registry.js";
import getChannel from "./get-channel.js";
import getReleaseInfo from "./get-release-info.js";

export default async function (npmrc, { npmPublish, pkgRoot }, pkg, context) {
  const {
    cwd,
    env,
    stdout,
    stderr,
    nextRelease: { version, channel },
    logger,
  } = context;

  if (npmPublish !== false && pkg.private !== true) {
    const basePath = pkgRoot ? path.resolve(cwd, pkgRoot) : cwd;
    const registry = getRegistry(pkg, context);
    const distTag = getChannel(channel);

    logger.log(`Publishing version ${version} to npm registry on dist-tag ${distTag}`);
    const result = execa(
      "npm",
      ["publish", basePath, "--userconfig", npmrc, "--tag", distTag, "--registry", registry],
      { cwd, env, preferLocal: true }
    );
    result.stdout.pipe(stdout, { end: false });
    result.stderr.pipe(stderr, { end: false });
    await result;

    logger.log(`Published ${pkg.name}@${version} to dist-tag @${distTag} on ${registry}`);

    return getReleaseInfo(pkg, context, distTag, registry);
  }

  logger.log(
    `Skip publishing to npm registry as ${npmPublish === false ? "npmPublish" : "package.json's private property"} is ${
      npmPublish !== false
    }`
  );

  return false;
}

const { log, output, META } = require('proc-log')
const semver = require('semver')
const pack = require('libnpmpack')
const libpub = require('libnpmpublish').publish
const runScript = require('@npmcli/run-script')
const pacote = require('pacote')
const npa = require('npm-package-arg')
const npmFetch = require('npm-registry-fetch')
const { redactLog: replaceInfo } = require('@npmcli/redact')
const { otplease } = require('../utils/auth.js')
const { getContents, logTar } = require('../utils/tar.js')
// for historical reasons, publishConfig in package.json can contain ANY config keys that npm supports in .npmrc files and elsewhere.
// We *may* want to revisit this at some point, and have a minimal set that's a SemVer-major change that ought to get a RFC written on it.
const { flatten } = require('@npmcli/config/lib/definitions')
const pkgJson = require('@npmcli/package-json')
const BaseCommand = require('../base-cmd.js')
const { oidc } = require('../utils/oidc.js')

class Publish extends BaseCommand {
  static description = 'Publish a package'
  static name = 'publish'
  static stage = false

  get isStage () {
    return this.constructor.stage
  }

  static params = [
    'tag',
    'access',
    'dry-run',
    'otp',
    'workspace',
    'workspaces',
    'include-workspace-root',
    'provenance',
  ]

  static usage = ['<package-spec>']
  static workspaces = true
  static ignoreImplicitWorkspace = false

  async exec (args) {
    if (args.length === 0) {
      args = ['.']
    }
    if (args.length !== 1) {
      throw this.usageError()
    }

    await this.#publish(args)
  }

  async execWorkspaces (args) {
    const useWorkspaces = args.length === 0 || args.includes('.')
    if (!useWorkspaces) {
      log.warn('Ignoring workspaces for specified package(s)')
      return this.exec(args)
    }
    await this.setWorkspaces()

    for (const [name, workspace] of this.workspaces.entries()) {
      try {
        await this.#publish([workspace], { workspace: name })
      } catch (err) {
        if (err.code !== 'EPRIVATE') {
          throw err
        }
        log.warn(this.#command, `Skipping workspace ${this.npm.chalk.cyan(name)}, marked as ${this.npm.chalk.bold('private')}`)
      }
    }
  }

  get #command () {
    return this.isStage ? 'stage' : 'publish'
  }

  async #publish (args, { workspace } = {}) {
    log.verbose(this.#command, replaceInfo(args))

    const unicode = this.npm.config.get('unicode')
    const dryRun = this.npm.config.get('dry-run')
    const json = this.npm.config.get('json')
    const defaultTag = this.npm.config.get('tag')
    const ignoreScripts = this.npm.config.get('ignore-scripts')
    const scriptShell = this.npm.config.get('script-shell') || undefined
    const { silent } = this.npm

    if (semver.validRange(defaultTag)) {
      throw new Error('Tag name must not be a valid SemVer range: ' + defaultTag.trim())
    }

    const opts = { ...this.npm.flatOptions, progress: false }

    // you can publish name@version, ./foo.tgz, etc even though the default is the 'file:.' cwd.
    const spec = npa(args[0])
    let manifest = await this.#getManifest(spec, opts)

    // packageExtensions is root-only project policy and must never be published; fail fast so dry-run reports it too
    this.#assertNoPackageExtensions(manifest)

    // only run scripts for directory type publishes
    if (spec.type === 'directory' && !ignoreScripts) {
      await runScript({
        event: 'prepublishOnly',
        path: spec.fetchSpec,
        stdio: 'inherit',
        pkg: manifest,
        scriptShell,
      })
    }

    // we pass dryRun: true to libnpmpack so it doesn't write the file to disk
    const tarballData = await pack(spec, {
      ...opts,
      foregroundScripts: this.npm.config.isDefault('foreground-scripts')
        ? true
        : this.npm.config.get('foreground-scripts'),
      dryRun: true,
      prefix: this.npm.localPrefix,
      workspaces: this.workspacePaths,
    })
    const pkgContents = await getContents(manifest, tarballData)
    const logPkg = () => logTar(pkgContents, { unicode, json, key: pkgContents.name })

    // The purpose of re-reading the manifest is in case it changed, so that we send the latest and greatest thing to the registry note that publishConfig might have changed as well!
    manifest = await this.#getManifest(spec, opts, true)
    // re-check the authoritative manifest in case a lifecycle script introduced packageExtensions
    this.#assertNoPackageExtensions(manifest)
    const force = this.npm.config.get('force')
    const isDefaultTag = this.npm.config.isDefault('tag') && !manifest.publishConfig?.tag

    if (!force) {
      const isPreRelease = Boolean(semver.parse(manifest.version).prerelease.length)
      if (isPreRelease && isDefaultTag) {
        throw new Error('You must specify a tag using --tag when publishing a prerelease version.')
      }
    }

    // If we are not in JSON mode then we show the user the contents of the tarball before it is published so they can see it while their otp is pending
    if (!json) {
      logPkg()
    }

    const resolved = npa.resolve(manifest.name, manifest.version)

    // make sure tag is valid, this will throw if invalid
    npa(`${manifest.name}@${defaultTag}`)

    const registry = npmFetch.pickRegistry(resolved, opts)

    await oidc({ packageName: manifest.name, registry, opts, config: this.npm.config })

    const creds = this.npm.config.getCredentialsByURI(registry)
    const noCreds = !(creds.token || creds.username || creds.certfile && creds.keyfile)
    const outputRegistry = replaceInfo(registry)

    if (workspace && manifest.private) {
      throw Object.assign(
        new Error(`This package has been marked as private
  Remove the 'private' field from the package.json to publish it.`),
        { code: 'EPRIVATE' }
      )
    }

    if (noCreds) {
      const msg = `This command requires you to be logged in to ${outputRegistry}`
      if (dryRun) {
        log.warn(this.#command, `${msg} (dry-run)`)
      } else {
        throw Object.assign(new Error(msg), { code: 'ENEEDAUTH' })
      }
    }

    if (!force) {
      const { highestVersion, versions } = await this.#registryVersions(resolved, registry)
      /* eslint-disable-next-line max-len */
      const highestVersionIsGreater = !!highestVersion && semver.gte(highestVersion, manifest.version)

      if (versions.includes(manifest.version)) {
        throw new Error(`You cannot publish over the previously published versions: ${manifest.version}.`)
      }

      if (highestVersionIsGreater && isDefaultTag) {
        throw new Error(`Cannot implicitly apply the "latest" tag because previously published version ${highestVersion} is higher than the new version ${manifest.version}. You must specify a tag using --tag.`)
      }
    }

    const access = opts.access === null ? 'default' : opts.access
    const verb = this.isStage ? 'Staging' : 'Publishing'
    let msg = `${verb} to ${outputRegistry} with tag ${defaultTag} and ${access} access`
    if (dryRun) {
      msg = `${msg} (dry-run)`
    }

    log.notice('', msg)

    let stageId
    if (!dryRun) {
      if (this.isStage) {
        // Stage intentionally bypasses otplease — 2FA is deferred to approve/reject
        const res = await libpub(manifest, tarballData, {
          ...opts,
          command: this.#command,
          stage: true,
        })
        stageId = res.stageId
      } else {
        await otplease(this.npm, opts, o => libpub(manifest, tarballData, o))
      }
    }

    // In json mode we don't log until the publish has completed as this will add it to the output only if completes successfully
    if (json) {
      if (stageId) {
        pkgContents.stageId = stageId
      }
      logTar(pkgContents, {
        unicode, json, key: pkgContents.name, redact: stageId ? false : undefined })
    }

    if (spec.type === 'directory' && !ignoreScripts) {
      await runScript({
        event: 'publish',
        path: spec.fetchSpec,
        stdio: 'inherit',
        pkg: manifest,
        scriptShell,
      })

      await runScript({
        event: 'postpublish',
        path: spec.fetchSpec,
        stdio: 'inherit',
        pkg: manifest,
        scriptShell,
      })
    }

    if (!json && !silent) {
      if (this.isStage) {
        const stagedMsg = stageId
          ? `+ ${pkgContents.id} (staged with id ${stageId})`
          : `+ ${pkgContents.id} (staged)`
        output.standard(stagedMsg, { [META]: true, redact: false })
        log.notice(this.#command, `package ${pkgContents.id} has been staged with tag ${defaultTag}`)
      } else {
        output.standard(`+ ${pkgContents.id}`)
      }
    }
  }

  async #registryVersions (spec, registry) {
    try {
      const packument = await pacote.packument(spec, {
        ...this.npm.flatOptions,
        preferOnline: true,
        registry,
        _isRoot: true,
      })
      if (typeof packument?.versions === 'undefined') {
        return { versions: [], highestVersion: null }
      }
      const ordered = Object.keys(packument?.versions)
        .flatMap(v => {
          const s = new semver.SemVer(v)
          if ((s.prerelease.length > 0) || packument.versions[v].deprecated) {
            return []
          }
          return s
        })
        .sort((a, b) => b.compare(a))
      const highestVersion = ordered.length >= 1 ? ordered[0].version : null
      const versions = ordered.map(v => v.version)
      return { versions, highestVersion }
    } catch (e) {
      return { versions: [], highestVersion: null }
    }
  }

  // packageExtensions is root-only project policy and must never reach the registry; private packages may keep it for local use
  #assertNoPackageExtensions (manifest) {
    if (!manifest.private && manifest.packageExtensions !== undefined) {
      throw Object.assign(
        new Error('packageExtensions is only honored at the project root and must not be published.'),
        { code: 'EPACKAGEEXTENSIONS' }
      )
    }
  }

  // if it's a directory, read it from the file system
  // otherwise, get the full metadata from whatever it is
  // XXX can't pacote read the manifest from a directory?
  async #getManifest (spec, opts, logWarnings = false) {
    let manifest
    if (spec.type === 'directory') {
      const changes = []
      const pkg = await pkgJson.fix(spec.fetchSpec, { changes })
      if (changes.length && logWarnings) {
        log.warn(this.#command, 'npm auto-corrected some errors in your package.json when publishing.  Please run "npm pkg fix" to address these errors.')
        log.warn(this.#command, `errors corrected:\n${changes.join('\n')}`)
      }
      // Prepare is the special function for publishing, different than normalize
      const { content } = await pkg.prepare()
      manifest = content
    } else {
      manifest = await pacote.manifest(spec, {
        ...opts,
        fullMetadata: true,
        fullReadJson: true,
      })
    }
    if (manifest.publishConfig) {
      const cliFlags = this.npm.config.data.get('cli').raw
      // Filter out properties set in CLI flags to prioritize them over corresponding `publishConfig` settings
      const filteredPublishConfig = Object.fromEntries(
        Object.entries(manifest.publishConfig).filter(([key]) => !(key in cliFlags)))
      if (logWarnings) {
        for (const key in filteredPublishConfig) {
          this.npm.config.checkUnknown('publishConfig', key)
        }
      }
      flatten(filteredPublishConfig, opts)
    }
    return manifest
  }
}

module.exports = Publish

import { resolve, basename, extname } from "node:path";
import { stat, readFile } from "node:fs/promises";

import { isPlainObject, template } from "lodash-es";
import mime from "mime";
import debugFactory from "debug";

import { RELEASE_NAME } from "./definitions/constants.js";
import parseGithubUrl from "./parse-github-url.js";
import globAssets from "./glob-assets.js";
import resolveConfig from "./resolve-config.js";
import { toOctokitOptions } from "./octokit.js";
import isPrerelease from "./is-prerelease.js";
import isLatestRelease from "./is-latest-release.js";

const debug = debugFactory("semantic-release:github");

export default async function publish(pluginConfig, context, { Octokit }) {
  const {
    cwd,
    options: { repositoryUrl },
    branch,
    nextRelease: { gitTag },
    logger,
  } = context;
  const {
    githubToken,
    githubUrl,
    githubApiPathPrefix,
    githubApiUrl,
    proxy,
    assets,
    draftRelease,
    releaseNameTemplate,
    releaseBodyTemplate,
    discussionCategoryName,
  } = resolveConfig(pluginConfig, context);
  const { owner, repo } = parseGithubUrl(repositoryUrl);
  const octokit = new Octokit(
    toOctokitOptions({
      githubToken,
      githubUrl,
      githubApiPathPrefix,
      githubApiUrl,
      proxy,
    }),
  );
  const release = {
    owner,
    repo,
    tag_name: gitTag,
    target_commitish: branch.name,
    name: template(releaseNameTemplate)(context),
    body: template(releaseBodyTemplate)(context),
    prerelease: isPrerelease(branch),
    make_latest: isLatestRelease(branch),
  };

  debug("release object: %O", release);

  const draftReleaseOptions = { ...release, draft: true };

  // When there are no assets, we publish a release directly.
  if (!assets || assets.length === 0) {
    // If draftRelease is true we create a draft release instead.
    if (draftRelease) {
      const {
        data: { html_url: url, id: releaseId },
      } = await octokit.request(
        "POST /repos/{owner}/{repo}/releases",
        draftReleaseOptions,
      );

      logger.log("Created GitHub draft release: %s", url);
      return { url, name: RELEASE_NAME, id: releaseId };
    }

    // add discussion_category_name if discussionCategoryName is not undefined or false
    if (discussionCategoryName) {
      release.discussion_category_name = discussionCategoryName;
    }

    const {
      data: { html_url: url, id: releaseId, discussion_url },
    } = await octokit.request("POST /repos/{owner}/{repo}/releases", release);

    logger.log("Published GitHub release: %s", url);

    if (discussionCategoryName) {
      logger.log("Created GitHub release discussion: %s", discussion_url);
    }

    return { url, name: RELEASE_NAME, id: releaseId, discussion_url };
  }

  // We'll create a draft release, append the assets to it, and then publish it.
  // This is so that the assets are available when we get a Github release event.
  const {
    data: { upload_url: uploadUrl, html_url: draftUrl, id: releaseId },
  } = await octokit.request(
    "POST /repos/{owner}/{repo}/releases",
    draftReleaseOptions,
  );

  // Append assets to the release
  const globbedAssets = await globAssets(context, assets);
  debug("globed assets: %o", globbedAssets);

  await Promise.all(
    globbedAssets.map(async (asset) => {
      const filePath = isPlainObject(asset) ? asset.path : asset;
      const resolved = resolve(cwd, filePath);
      let file;

      try {
        file = await stat(resolved);
      } catch {
        logger.error(
          "The asset %s cannot be read, and will be ignored.",
          filePath,
        );
        return;
      }

      if (!file || !file.isFile()) {
        logger.error(
          "The asset %s is not a file, and will be ignored.",
          resolved,
        );
        return;
      }

      const fileName = template(asset.name || basename(filePath))(context);
      const upload = {
        method: "POST",
        url: uploadUrl,
        data: await readFile(resolved),
        name: fileName,
        headers: {
          "content-type": mime.getType(extname(fileName)) || "text/plain",
        },
      };

      debug("file path: %o", filePath);
      debug("file name: %o", fileName);

      if (isPlainObject(asset) && asset.label) {
        upload.label = template(asset.label)(context);
      }

      const {
        data: { browser_download_url: downloadUrl },
      } = await octokit.request(upload);
      logger.log("Published file %s", downloadUrl);
    }),
  );

  // If we want to create a draft we don't need to update the release again
  if (draftRelease) {
    logger.log("Created GitHub draft release: %s", draftUrl);
    return { url: draftUrl, name: RELEASE_NAME, id: releaseId };
  }

  const patchRelease = {
    owner,
    repo,
    release_id: releaseId,
    draft: false,
    make_latest: isLatestRelease(branch),
  };

  // add discussion_category_name if discussionCategoryName is not undefined or false
  if (discussionCategoryName) {
    patchRelease.discussion_category_name = discussionCategoryName;
  }

  const {
    data: { html_url: url, discussion_url },
  } = await octokit.request(
    "PATCH /repos/{owner}/{repo}/releases/{release_id}",
    patchRelease,
  );

  logger.log("Published GitHub release: %s", url);

  if (discussionCategoryName) {
    logger.log("Created GitHub release discussion: %s", discussion_url);
  }

  return { url, name: RELEASE_NAME, id: releaseId, discussion_url };
}

'use strict';

module.exports = exports = install;

exports.usage = 'Attempts to install pre-built binary for module';

const fs = require('fs');
const path = require('path');
const log = require('./util/log.js');
const existsAsync = fs.exists || path.exists;
const versioning = require('./util/versioning.js');
const napi = require('./util/napi.js');
const s3_setup = require('./util/s3_setup.js');
const url = require('url');
// for fetching binaries
const fetch = require('node-fetch');
const tar = require('tar');

let npgVersion = 'unknown';
try {
  // Read own package.json to get the current node-pre-pyp version.
  const ownPackageJSON = fs.readFileSync(path.join(__dirname, '..', 'package.json'), 'utf8');
  npgVersion = JSON.parse(ownPackageJSON).version;
} catch (e) {
  // do nothing
}

function place_binary_authenticated(opts, targetDir, callback) {
  log.info('install', 'Attempting authenticated S3 download');

  // Check if AWS credentials are available
  if (!process.env.AWS_ACCESS_KEY_ID || !process.env.AWS_SECRET_ACCESS_KEY) {
    const err = new Error('Binary is private but AWS credentials not found. Please configure AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY environment variables, or use --fallback-to-build to compile from source.');
    err.statusCode = 403;
    return callback(err);
  }

  try {
    const config = s3_setup.detect(opts);
    const s3 = s3_setup.get_s3(config);
    const key_name = url.resolve(config.prefix, opts.package_name);

    log.info('install', 'Downloading from S3:', config.bucket, key_name);

    const s3_opts = {
      Bucket: config.bucket,
      Key: key_name
    };

    s3.getObject(s3_opts, (err, data) => {
      if (err) {
        log.error('install', 'Authenticated S3 download failed:', err.message);
        return callback(err);
      }

      log.info('install', 'Authenticated download successful, extracting...');

      const { Readable } = require('stream');
      const dataStream = Readable.from(data.Body);

      let extractions = 0;
      const countExtractions = (entry) => {
        extractions += 1;
        log.info('install', `unpacking ${entry.path}`);
      };

      dataStream.pipe(extract(targetDir, countExtractions))
        .on('error', (e) => {
          callback(e);
        })
        .on('close', () => {
          log.info('install', `extracted file count: ${extractions}`);
          callback();
        });
    });
  } catch (e) {
    if (e.code === 'MODULE_NOT_FOUND' && e.message.includes('@aws-sdk/client-s3')) {
      const err = new Error('Binary is private and requires @aws-sdk/client-s3 for authenticated download. Please run: npm install @aws-sdk/client-s3');
      err.statusCode = 403;
      return callback(err);
    }
    log.error('install', 'Error setting up authenticated download:', e.message);
    callback(e);
  }
}

function place_binary(uri, targetDir, opts, callback) {
  log.log('GET', uri);

  // Try getting version info from the currently running npm.
  const envVersionInfo = process.env.npm_config_user_agent ||
        'node ' + process.version;

  const sanitized = uri.replace('+', '%2B');
  const requestOpts = {
    uri: sanitized,
    headers: {
      'User-Agent': 'node-pre-gyp (v' + npgVersion + ', ' + envVersionInfo + ')'
    },
    follow_max: 10
  };

  if (opts.cafile) {
    try {
      requestOpts.ca = fs.readFileSync(opts.cafile);
    } catch (e) {
      return callback(e);
    }
  } else if (opts.ca) {
    requestOpts.ca = opts.ca;
  }

  const proxyUrl = opts.proxy ||
                    process.env.http_proxy ||
                    process.env.HTTP_PROXY ||
                    process.env.npm_config_proxy;
  let agent;
  if (proxyUrl) {
    const { HttpsProxyAgent } = require('https-proxy-agent');
    agent = new HttpsProxyAgent(proxyUrl);
    log.log('download', `proxy agent configured using: "${proxyUrl}"`);
  }

  fetch(sanitized, { agent })
    .then((res) => {
      if (!res.ok) {
        // If we get 403 Forbidden, the binary might be private - try authenticated download
        if (res.status === 403) {
          log.info('install', 'Received 403 Forbidden - attempting authenticated download');
          // Call place_binary_authenticated and return a special marker
          // to prevent the promise chain from calling callback again
          place_binary_authenticated(opts, targetDir, callback);
          return { authenticated: true };
        }
        throw new Error(`response status ${res.status} ${res.statusText} on ${sanitized}`);
      }
      const dataStream = res.body;

      return new Promise((resolve, reject) => {
        let extractions = 0;
        const countExtractions = (entry) => {
          extractions += 1;
          log.info('install', `unpacking ${entry.path}`);
        };

        dataStream.pipe(extract(targetDir, countExtractions))
          .on('error', (e) => {
            reject(e);
          });
        dataStream.on('end', () => {
          resolve(`extracted file count: ${extractions}`);
        });
        dataStream.on('error', (e) => {
          reject(e);
        });
      });
    })
    .then((text) => {
      if (text && text.authenticated) {
        return; // Don't call callback - place_binary_authenticated will handle it
      }
      log.info(text);
      callback();
    })
    .catch((e) => {
      log.error(`install ${e.message}`);
      callback(e);
    });
}

function extract(to, onentry) {
  return tar.extract({
    cwd: to,
    strip: 1,
    onentry
  });
}

function extract_from_local(from, targetDir, callback) {
  if (!fs.existsSync(from)) {
    return callback(new Error('Cannot find file ' + from));
  }
  log.info('Found local file to extract from ' + from);

  // extract helpers
  let extractCount = 0;
  function countExtractions(entry) {
    extractCount += 1;
    log.info('install', 'unpacking ' + entry.path);
  }
  function afterExtract(err) {
    if (err) return callback(err);
    if (extractCount === 0) {
      return callback(new Error('There was a fatal problem while extracting the tarball'));
    }
    log.info('tarball', 'done parsing tarball');
    callback();
  }

  fs.createReadStream(from).pipe(extract(targetDir, countExtractions))
    .on('close', afterExtract)
    .on('error', afterExtract);
}

function do_build(gyp, argv, callback) {
  const args = ['rebuild'].concat(argv);
  gyp.todo.push({ name: 'build', args: args });
  process.nextTick(callback);
}

function print_fallback_error(err, opts, package_json) {
  const fallback_message = ' (falling back to source compile with node-gyp)';
  let full_message = '';
  if (err.statusCode !== undefined) {
    // If we got a network response it but failed to download
    // it means remote binaries are not available, so let's try to help
    // the user/developer with the info to debug why
    full_message = 'Pre-built binaries not found for ' + package_json.name + '@' + package_json.version;
    full_message += ' and ' + opts.runtime + '@' + (opts.target || process.versions.node) + ' (' + opts.node_abi + ' ABI, ' + opts.libc + ')';
    full_message += fallback_message;
    log.warn('Tried to download(' + err.statusCode + '): ' + opts.hosted_tarball);
    log.warn(full_message);
    log.error(err.message);
  } else {
    // If we do not have a statusCode that means an unexpected error
    // happened and prevented an http response, so we output the exact error
    full_message = 'Pre-built binaries not installable for ' + package_json.name + '@' + package_json.version;
    full_message += ' and ' + opts.runtime + '@' + (opts.target || process.versions.node) + ' (' + opts.node_abi + ' ABI, ' + opts.libc + ')';
    full_message += fallback_message;
    log.warn(full_message);
    log.warn('Hit error ' + err.message);
  }
}

//
// install
//
function install(gyp, argv, callback) {
  const package_json = gyp.package_json;
  const napi_build_version = napi.get_napi_build_version_from_command_args(argv);
  const source_build = gyp.opts['build-from-source'] || gyp.opts.build_from_source;
  const update_binary = gyp.opts['update-binary'] || gyp.opts.update_binary;
  const should_do_source_build = source_build === package_json.name || (source_build === true || source_build === 'true');
  if (should_do_source_build) {
    log.info('build', 'requesting source compile');
    return do_build(gyp, argv, callback);
  } else {
    const fallback_to_build = gyp.opts['fallback-to-build'] || gyp.opts.fallback_to_build;
    let should_do_fallback_build = fallback_to_build === package_json.name || (fallback_to_build === true || fallback_to_build === 'true');
    // but allow override from npm
    if (process.env.npm_config_argv) {
      const cooked = JSON.parse(process.env.npm_config_argv).cooked;
      const match = cooked.indexOf('--fallback-to-build');
      if (match > -1 && cooked.length > match && cooked[match + 1] === 'false') {
        should_do_fallback_build = false;
        log.info('install', 'Build fallback disabled via npm flag: --fallback-to-build=false');
      }
    }
    let opts;
    try {
      opts = versioning.evaluate(package_json, gyp.opts, napi_build_version);
    } catch (err) {
      return callback(err);
    }

    opts.ca = gyp.opts.ca;
    opts.cafile = gyp.opts.cafile;

    const from = opts.hosted_tarball;
    const to = opts.module_path;
    const binary_module = path.join(to, opts.module_name + '.node');
    existsAsync(binary_module, (found) => {
      if (!update_binary) {
        if (found) {
          console.log('[' + package_json.name + '] Success: "' + binary_module + '" already installed');
          console.log('Pass --update-binary to reinstall or --build-from-source to recompile');
          return callback();
        }
        log.info('check', 'checked for "' + binary_module + '" (not found)');
      }

      fs.promises.mkdir(to, { recursive: true }).then(() => {
        const fileName = from.startsWith('file://') && from.slice('file://'.length);
        if (fileName) {
          extract_from_local(fileName, to, after_place);
        } else {
          place_binary(from, to, opts, after_place);
        }
      }).catch((err) => {
        after_place(err);
      });

      function after_place(err) {
        if (err && should_do_fallback_build) {
          print_fallback_error(err, opts, package_json);
          return do_build(gyp, argv, callback);
        } else if (err) {
          return callback(err);
        } else {
          console.log('[' + package_json.name + '] Success: "' + binary_module + '" is installed via remote');
          return callback();
        }
      }
    });
  }
}

